const { sentryEsbuildPlugin } = require("@sentry/esbuild-plugin");

const sourcemap = (() => {
  if (process.env.SOURCEMAP_UPLOAD === "true") {
    return "external";
  }
  if (process.env.NODE_ENV === "development") {
    return "inline";
  }
  return undefined;
})();

module.exports = {
  sourcemap,
  keepNames: true,
  plugins: [
    sentryEsbuildPlugin({
      disable: process.env.SOURCEMAP_UPLOAD !== "true",
      authToken: process.env.SENTRY_AUTH_TOKEN,
      org: "recipesage",
      project: "recipesage-api",
    }),
  ],
};

import * as Sentry from "@sentry/node";

import {
  NotFoundError,
  ServerError,
  rateLimitHandler,
  typesafeExpressIndexRouter,
  generateExpressOpenApiParts,
} from "@recipesage/express";

import express from "express";
import compression from "compression";
import logger from "morgan";
import cookieParser from "cookie-parser";
import bodyParser from "body-parser";
import cors from "cors";

import {
  trpcExpressMiddleware,
  openApiDocument,
  openApiExpressMiddleware,
} from "@recipesage/trpc";

import { setupInvalidateStaleJobsInterval } from "@recipesage/util/server/db";
setupInvalidateStaleJobsInterval();
import { metrics, config } from "@recipesage/util/server/general";

// Routes
import index from "./routes/index.js";
import images from "./routes/images.js";

import { ErrorRequestHandler } from "express";

const app = express();

app.set("trust proxy", config.rateLimit.trustProxyHops);

app.use(compression());

const defaultCorsAllowlist = [
  "https://www.recipesage.com",
  "https://recipesage.com",
  "https://beta.recipesage.com",
  "https://api.recipesage.com",
  "https://windows.recipesage.com",
  "https://android.recipesage.com",
  "https://ios.recipesage.com",
  "https://desktop-vhost.recipesage.com",
  "https://localhost",
  "capacitor://localhost",
  "moz-extension://*",
  "chrome-extension://*",
];

const hostMatch = (pattern: string, origin: string) => {
  if (pattern.endsWith("*")) {
    return origin.startsWith(pattern.substring(0, pattern.length - 1));
  }

  return origin === pattern;
};

const corsOptions = {
  origin: (origin, callback) => {
    if (process.env.CORS_ALLOWLIST) {
      const allowList = process.env.CORS_ALLOWLIST.split(",");
      const allowCors =
        origin && allowList.some((pattern) => hostMatch(pattern, origin));
      callback(null, allowCors);
      return;
    }

    if (process.env.NODE_ENV === "selfhost") {
      // No default allowlist, so we do not know selfhost user's origin
      // we allow all.
      callback(null, true);
      return;
    }

    const allowCors =
      origin &&
      defaultCorsAllowlist.some((pattern) => hostMatch(pattern, origin));
    callback(null, allowCors);
  },
} satisfies cors.CorsOptions;

app.use(cors(corsOptions));
app.use(cookieParser());

const rateLimitExemptPrefixes = ["/metrics", "/stripe/webhook", "/health"];
const globalRateLimitHandler = rateLimitHandler("global");
app.use((req, res, next) => {
  if (rateLimitExemptPrefixes.some((prefix) => req.path.startsWith(prefix))) {
    next();
    return;
  }
  globalRateLimitHandler(req, res, next);
});

const EXPRESS_VIEWS_PATH = process.env.EXPRESS_VIEWS_PATH;
if (!EXPRESS_VIEWS_PATH) throw new Error("EXPRESS_VIEWS_PATH must be provided");
app.set("views", EXPRESS_VIEWS_PATH);
app.set("view engine", "pug");

if (process.env.NODE_ENV !== "test") app.use(logger("dev"));
app.use(
  bodyParser.json({
    limit: "2MB",
    verify: (req, res, buf) => {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const url = (req as any).originalUrl;
      if (url.startsWith("/stripe/webhook")) {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        (req as any).rawBody = buf.toString();
      }
    },
  }),
);

app.use(function (req, res, next) {
  const timer = metrics.apiRequest.startTimer();
  res.on("finish", function () {
    const time = timer();
    const path = req.baseUrl + (req.route?.path || req.path);

    // We don't capture 404s here because endpoint probing blows up our cardinality
    if (res.statusCode !== 404) {
      metrics.apiRequest.observe(
        {
          status_code: res.statusCode,
          method: req.method,
          path,
        },
        time,
      );
    }
  });

  next();
});

app.use(bodyParser.urlencoded({ limit: "1MB", extended: false }));
app.use(cookieParser());
app.disable("x-powered-by");
app.use("/", typesafeExpressIndexRouter);
app.use("/", index);
app.use("/trpc", trpcExpressMiddleware);

const mergeOpenApiEntries = <T>(
  label: string,
  base: Record<string, T> | undefined,
  extra: Record<string, T> | undefined,
): Record<string, T> => {
  const merged: Record<string, T> = { ...base };
  for (const [key, value] of Object.entries(extra ?? {})) {
    if (
      key in merged &&
      JSON.stringify(merged[key]) !== JSON.stringify(value)
    ) {
      throw new Error(
        `OpenAPI ${label} collision: "${key}" is defined by both the tRPC and Express specs with differing definitions`,
      );
    }
    merged[key] = value;
  }
  return merged;
};

const expressOpenApiParts = generateExpressOpenApiParts();
const mergedOpenApiDocument = {
  ...openApiDocument,
  servers: [{ url: config.api.publicUrl }],
  paths: mergeOpenApiEntries(
    "path",
    openApiDocument.paths,
    expressOpenApiParts.paths,
  ),
  components: {
    ...openApiDocument.components,
    securitySchemes: mergeOpenApiEntries(
      "securityScheme",
      openApiDocument.components?.securitySchemes,
      expressOpenApiParts.securitySchemes,
    ),
    schemas: mergeOpenApiEntries(
      "schema",
      openApiDocument.components?.schemas,
      expressOpenApiParts.schemas,
    ),
  },
};
const assertUniqueOperationIds = (
  paths: typeof mergedOpenApiDocument.paths,
) => {
  const seen = new Set<string>();
  for (const pathItem of Object.values(paths)) {
    const operations = [
      pathItem.get,
      pathItem.post,
      pathItem.put,
      pathItem.patch,
      pathItem.delete,
    ];
    for (const operation of operations) {
      const operationId = operation?.operationId;
      if (!operationId) continue;
      if (seen.has(operationId)) {
        throw new Error(
          `OpenAPI operationId collision: "${operationId}" is defined by more than one operation`,
        );
      }
      seen.add(operationId);
    }
  }
};
assertUniqueOperationIds(mergedOpenApiDocument.paths);

const serveOpenApiDocument = (_req: express.Request, res: express.Response) => {
  res.json(mergedOpenApiDocument);
};
app.get("/openapi.json", serveOpenApiDocument);
app.get("/compat/openapi.json", serveOpenApiDocument);
app.use("/compat/v2", openApiExpressMiddleware);
app.use("/images", images);

// catch 404 and forward to error handler
app.use(function (req, res, next) {
  const err = new NotFoundError("Not Found");
  next(err);
});

const logError = (err: ServerError) => {
  // Do not log expected RESTful errors
  const isExpectedError = err.status < 500 || err.status > 599;
  if (isExpectedError) return;

  console.error(err);
};

const appErrorHandler: ErrorRequestHandler = function (_err, req, res, _next) {
  const err = _err as ServerError;
  if (!err.status) err.status = 500;

  // set locals, only providing error in development
  res.locals.message = err.message;

  res.locals.error = process.env.NODE_ENV === "production" ? {} : err;

  logError(err);

  // render the error page
  res.status(err.status);
  res.render("error");
};

Sentry.setupExpressErrorHandler(app);
app.use(appErrorHandler);

export { app };

export default app;

#!/usr/bin/env node

import "./sentry-init.js";

/**
 * Module dependencies.
 */

import { app } from "./app";
import Debug from "debug";
const debug = Debug("chefbook-backend:server");
import protocol from "http";
import { getJobQueueWorker } from "@recipesage/util/server/general";

/**
 * Get port from environment and store in Express.
 */
const port = normalizePort(process.env.PORT || "3000");
app.set("port", port);

/**
 * Create HTTP server.
 */
export const server = protocol.createServer(app);

/**
 * Listen on provided port, on all network interfaces.
 */
server.listen(port);
server.on("error", onError);
server.on("listening", onListening);

/**
 * Normalize a port into a number, string, or false.
 */
function normalizePort(val: string) {
  const port = parseInt(val, 10);

  if (isNaN(port)) {
    // named pipe
    return val;
  }

  if (port >= 0) {
    // port number
    return port;
  }

  return false;
}

/**
 * Event listener for HTTP server "error" event.
 */
function onError(error: Error & { syscall: string; code: string }) {
  if (error.syscall !== "listen") {
    throw error;
  }

  const bind = typeof port === "string" ? "Pipe " + port : "Port " + port;

  // handle specific listen errors with friendly messages
  switch (error.code) {
    case "EACCES":
      console.error(bind + " requires elevated privileges");
      return process.exit(1);
    case "EADDRINUSE":
      console.error(bind + " is already in use");
      return process.exit(1);
    default:
      throw error;
  }
}

/**
 * Event listener for HTTP server "listening" event.
 */
function onListening() {
  const addr = server.address();
  const bind = typeof addr === "string" ? "pipe " + addr : "port " + addr?.port;
  debug("Listening on " + bind);
}

const termHandler = async () => {
  if (process.env.NODE_ENV !== "production") {
    process.exit(0);
  }

  console.log("RECEIVED SIGNAL - CLOSING SERVER");
  server.close(() => {
    process.exit(0);
  });
};

process.on("SIGTERM", termHandler);
process.on("SIGINT", termHandler);

if (process.env.NODE_ENV === "selfhost") {
  getJobQueueWorker().run();
}

import * as Sentry from "@sentry/node";
import { nodeProfilingIntegration } from "@sentry/profiling-node";
import { getHTTPStatusCodeFromError } from "@trpc/server/http";
import { TRPCError } from "@trpc/server";

const RS_VERSION = process.env.VERSION || "VERSION-missing";

const CLIENT_DISCONNECT_MESSAGES = new Set([
  "Request aborted",
  "Request closed",
]);

Sentry.init({
  dsn: process.env.SENTRY_DSN,

  integrations: [
    nodeProfilingIntegration(),
    Sentry.prismaIntegration(),
    Sentry.httpIntegration(),
    Sentry.expressIntegration(),
  ],

  sampleRate: parseFloat(process.env.SENTRY_ERROR_SAMPLE_RATE ?? "1.0"),
  tracesSampleRate: parseFloat(process.env.SENTRY_TRACE_SAMPLE_RATE ?? "1.0"),
  profilesSampleRate: parseFloat(
    process.env.SENTRY_PROFILE_SAMPLE_RATE ?? "1.0",
  ),
  profileLifecycle: "trace",

  environment: process.env.ENVIRONMENT || "unknown",
  release: RS_VERSION,

  beforeSend: (event, hint) => {
    if (
      hint.originalException instanceof Error &&
      hint.originalException.name === "Error" &&
      CLIENT_DISCONNECT_MESSAGES.has(hint.originalException.message)
    ) {
      return null;
    }

    if (hint.originalException instanceof TRPCError) {
      const statusCode = getHTTPStatusCodeFromError(hint.originalException);

      // We do not want to log non-500 errors
      if (statusCode < 500) return null;

      event.tags = {
        ...event.tags,
        trpc_code: hint.originalException.code,
        trpc_statuscode: statusCode,
      };

      console.error(hint.originalException.cause || hint.originalException);
    }

    return event;
  },
});

