import { prisma } from "@recipesage/prisma";
import {
  extendSubscription,
  SubscriptionModelName,
} from "@recipesage/util/server/capabilities";

export const activateBonusFeatures = async (args: {
  email: string;
  subscriptionName?: string;
}) => {
  const validSubscriptionNames = Object.values(SubscriptionModelName);

  const requestedName = args.subscriptionName ?? SubscriptionModelName.Forever;
  const subscriptionName = validSubscriptionNames.find(
    (v) => v === requestedName,
  );

  if (!subscriptionName) {
    throw new Error(
      `Unknown subscription name: "${requestedName}". Valid options: ${validSubscriptionNames.join(", ")}`,
    );
  }

  const user = await prisma.user.findUnique({
    where: { email: args.email },
  });

  if (!user) {
    console.log("No user found with that email address");
    return;
  }

  await extendSubscription(user.id, subscriptionName);

  console.log("");
  console.log("Thanks for activating RecipeSage's bonus features");
  console.log(
    "Please consider contributing to RecipeSage's development & maintenance: https://recipesage.com/app/contribute",
  );
  console.log("");
  console.log("- Julian");
  console.log("");
};

import * as Sentry from "@sentry/node";

import { prisma } from "@recipesage/prisma";
import { getShoppingListItemCategories } from "@recipesage/util/server/general";

const waitFor = async (timeout: number) => {
  return new Promise((resolve) => {
    setTimeout(resolve, timeout);
  });
};

export const categorizeShoppingListItems = async () => {
  try {
    while (true) {
      const items = await prisma.shoppingListItem.findMany({
        where: {
          categoryTitle: null,
        },
        select: {
          id: true,
          title: true,
        },
        take: 40,
      });

      if (!items.length) {
        console.log("Categorization complete!");
        return;
      }

      const categoryTitles = await getShoppingListItemCategories(
        items.map((el) => el.title),
      );

      for (let i = 0; i < items.length; i++) {
        const item = items[i];
        const categoryTitle = `::${categoryTitles[i]}`;

        await prisma.shoppingListItem.update({
          where: {
            id: item.id,
          },
          data: {
            categoryTitle,
          },
        });
        await waitFor(100);
      }
    }
  } catch (e) {
    Sentry.captureException(e);
    console.log("Error while processing", e);
    throw e;
  }
};

import { readFile, writeFile } from "fs/promises";

import { decryptWithRSAKey } from "@recipesage/util/server/general";

export const decryptDebugStore = async (args: {
  input: string;
  output: string;
}) => {
  if (!process.env.DEBUG_DUMP_PRIVATE_KEY) {
    throw new Error(
      "It looks like env.DEBUG_DUMP_PRIVATE_KEY isn't present. You'll need that to decrypt the dump",
    );
  }

  const encryptedJsonString = await readFile(args.input, "utf8");
  if (!encryptedJsonString) {
    throw new Error("It looks like the input json file does not exist");
  }

  const decryptedBlob = decryptWithRSAKey(
    encryptedJsonString,
    process.env.DEBUG_DUMP_PRIVATE_KEY,
  );

  const text = decryptedBlob.toString();

  const prettyJson = JSON.stringify(JSON.parse(text), undefined, 2);

  await writeFile(args.output, prettyJson);

  console.log("Done!");
};

import * as Sentry from "@sentry/node";

import { Prisma, prisma } from "@recipesage/prisma";

const waitFor = async (timeout: number) => {
  return new Promise((resolve) => {
    setTimeout(resolve, timeout);
  });
};

const RECIPES_TSV = Prisma.sql`
  setweight(to_tsvector('simple', immutable_unaccent(left(coalesce(title, ''), 255))), 'A') ||
  setweight(to_tsvector('simple', immutable_unaccent(left(coalesce(description, ''), 255))), 'B') ||
  setweight(to_tsvector('simple', immutable_unaccent(left(coalesce(ingredients, ''), 3000))), 'B') ||
  setweight(to_tsvector('simple', immutable_unaccent(left(coalesce(source, ''), 255))), 'C') ||
  setweight(to_tsvector('simple', immutable_unaccent(left(coalesce(notes, ''), 3000))), 'C')
`;

const DISCOVER_RECIPES_TSV = Prisma.sql`
  setweight(to_tsvector('simple', immutable_unaccent(left(coalesce(title, ''), 255))), 'A') ||
  setweight(to_tsvector('simple', immutable_unaccent(left(coalesce(description, ''), 255))), 'B') ||
  setweight(to_tsvector('simple', immutable_unaccent(left(coalesce(ingredients, ''), 3000))), 'B') ||
  setweight(to_tsvector('simple', immutable_unaccent(left(coalesce(notes, ''), 3000))), 'C')
`;

const backfillTsv = async (
  table: Prisma.Sql,
  expr: Prisma.Sql,
  batchSize: number,
  batchInterval: number,
) => {
  let lastId = "00000000-0000-0000-0000-000000000000";

  while (true) {
    const rows = await prisma.$queryRaw<{ id: string }[]>(Prisma.sql`
      SELECT id FROM ${table} WHERE id > ${lastId}::uuid ORDER BY id LIMIT ${batchSize}
    `);

    if (rows.length === 0) return;

    lastId = rows[rows.length - 1].id;

    const updated = await prisma.$executeRaw(Prisma.sql`
      UPDATE ${table} SET tsv = ${expr}
      WHERE id = ANY(${rows.map((r) => r.id)}::uuid[])
        AND tsv IS DISTINCT FROM (${expr})
    `);

    if (updated > 0) {
      console.log(`Backfilled ${updated} rows through ${lastId}`);
    }

    await waitFor(batchInterval * 1000);
  }
};

const runPostgresBackfill = async (
  batchSize: number,
  batchInterval: number,
) => {
  await backfillTsv(
    Prisma.sql`"Recipes"`,
    RECIPES_TSV,
    batchSize,
    batchInterval,
  );
  await backfillTsv(
    Prisma.sql`"Discover_Recipes"`,
    DISCOVER_RECIPES_TSV,
    batchSize,
    batchInterval,
  );

  console.log("Postgres FTS backfill complete!");
};

export const indexRecipes = async (args: {
  batchSize: number;
  batchInterval: number;
}) => {
  try {
    await runPostgresBackfill(args.batchSize, args.batchInterval);
  } catch (e) {
    Sentry.captureException(e);
    console.log("Error while indexing", e);
    throw e;
  }
};

import "./sentry-init.js";
import { program } from "commander";

import { activateBonusFeatures } from "./activateBonusFeatures";
import { categorizeShoppingListItems } from "./categorizeShoppingListItems";
import { decryptDebugStore } from "./decryptDebugStore";
import { indexRecipes } from "./indexRecipes";
import { recomputeDiscoverRankScores } from "./recomputeDiscoverRankScores";

const runAction =
  <O>(fn: (options: O) => Promise<void>) =>
  async (options: O) => {
    try {
      await fn(options);
      process.exit(0);
    } catch (e) {
      console.error(e);
      process.exit(1);
    }
  };

program.name("recipesage").description("RecipeSage CLI");

program
  .command("indexRecipes")
  .description("Backfill the Postgres full-text search tsv columns.")
  .option("-b, --batch-size <size>", "Batch size", "1000")
  .option("-i, --batch-interval <interval>", "Batch interval in seconds", "1")
  .action(
    runAction<{ batchSize: string; batchInterval: string }>(async (options) => {
      await indexRecipes({
        batchSize: parseInt(options.batchSize, 10),
        batchInterval: parseFloat(options.batchInterval),
      });
    }),
  );

program
  .command("categorizeShoppingListItems")
  .description("Categorize uncategorized shopping list items.")
  .action(
    runAction(async () => {
      await categorizeShoppingListItems();
    }),
  );

program
  .command("recomputeDiscoverRankScores")
  .description(
    "Recompute the smart-ranking score for every discover recipe. Intended to be scheduled (for example, as a Kubernetes CronJob).",
  )
  .option("-b, --batch-size <size>", "Batch size", "1000")
  .action(
    runAction<{ batchSize: string }>(async (options) => {
      await recomputeDiscoverRankScores({
        batchSize: parseInt(options.batchSize, 10),
      });
    }),
  );

program
  .command("activateBonusFeatures")
  .description(
    "Activate bonus features (a subscription) for a user by email address.",
  )
  .requiredOption("--email <email>", "The user's email address")
  .option(
    "--subscription-name <name>",
    "Subscription model name (forever, pyo-monthly, pyo-yearly, pyo-single)",
    "forever",
  )
  .action(
    runAction<{ email: string; subscriptionName: string }>(async (options) => {
      await activateBonusFeatures({
        email: options.email,
        subscriptionName: options.subscriptionName,
      });
    }),
  );

program
  .command("decryptDebugStore")
  .description("Decrypt an encrypted debug store dump.")
  .requiredOption("--input <input>", "Input filename")
  .requiredOption("--output <output>", "Output filename")
  .action(
    runAction<{ input: string; output: string }>(async (options) => {
      await decryptDebugStore({
        input: options.input,
        output: options.output,
      });
    }),
  );

const close = (signal: string) => {
  console.log(`RECEIVED ${signal} - STOPPING JOB`);
  process.exit(0);
};

process.on("SIGTERM", () => close("SIGTERM"));
process.on("SIGINT", () => close("SIGINT"));

program.parseAsync(process.argv).catch((e) => {
  console.error(e);
  process.exit(1);
});

import * as Sentry from "@sentry/node";

import { Prisma, prisma } from "@recipesage/prisma";
import {
  computeDiscoverRankScore,
  getDiscoverDistinctSaverCounts,
} from "@recipesage/util/server/db";

export const recomputeDiscoverRankScores = async (options: {
  batchSize: number;
}) => {
  try {
    const now = new Date();
    let cursor: string | undefined;
    let processed = 0;

    while (true) {
      const discoverRecipes = await prisma.discoverRecipe.findMany({
        select: {
          id: true,
          createdAt: true,
          ratingAverage: true,
          ratingCount: true,
        },
        orderBy: {
          id: "asc",
        },
        take: options.batchSize,
        ...(cursor
          ? {
              skip: 1,
              cursor: {
                id: cursor,
              },
            }
          : {}),
      });

      if (!discoverRecipes.length) break;

      const saverCounts = await getDiscoverDistinctSaverCounts(
        discoverRecipes.map((discoverRecipe) => discoverRecipe.id),
      );

      const valueTuples = discoverRecipes.map((discoverRecipe) => {
        const saveCount = saverCounts.get(discoverRecipe.id) ?? 0;
        const rankScore = computeDiscoverRankScore({
          createdAt: discoverRecipe.createdAt,
          saveCount,
          ratingAverage: discoverRecipe.ratingAverage,
          ratingCount: discoverRecipe.ratingCount,
          now,
        });
        return Prisma.sql`(${discoverRecipe.id}::uuid, ${saveCount}::integer, ${rankScore}::double precision)`;
      });

      await prisma.$executeRaw(Prisma.sql`
        UPDATE "Discover_Recipes" AS d
        SET "saveCount" = v.saveCount, "rankScore" = v.rankScore
        FROM (VALUES ${Prisma.join(valueTuples)}) AS v(id, saveCount, rankScore)
        WHERE d.id = v.id
      `);

      processed += discoverRecipes.length;
      cursor = discoverRecipes[discoverRecipes.length - 1].id;
      console.log(`Recomputed rank scores for ${processed} discover recipes`);
    }

    console.log("Discover rank score recompute complete!");
  } catch (e) {
    Sentry.captureException(e);
    console.log("Error while recomputing discover rank scores", e);
    throw e;
  }
};

