    expect(response.status).toBe(201);
    expect(response.body).toEqual({ jobId: "abc" });
    expect(captureExceptionMock).not.toHaveBeenCalled();
  });
});

import { Handler, NextFunction, Request, Response } from "express";
import { ZodError, ZodSchema } from "zod";
import {
  BadRequestError,
  InternalServerError,
  ServerError,
  UnauthorizedError,
} from "./errors";
import { logError } from "./logError";
import {
  validateSession,
  extendSession,
  RateLimitTier,
} from "@recipesage/util/server/general";
import { Session } from "@recipesage/prisma";
import { rateLimitHandler } from "./rateLimitHandler";
import { OpenApiRouteMeta, registerOpenApiRoute } from "./openapi/registry";
import { AuthenticationEnforcement } from "./authenticationEnforcement";

const handleServerError = (e: unknown, res: Response) => {
  if (e instanceof ServerError) {
    logError(e);

    if (process.env.NODE_ENV !== "production") {
      res.status(e.status).send(e);
    } else {
      res.status(e.status).send(e.name);
    }
  } else {
    logError(e);

    if (process.env.NODE_ENV !== "production") {
      res.status(500).send(e);
    } else {
      res.status(500).send("Internal server error");
    }
  }
};

type SessionPresent = {
  [AuthenticationEnforcement.Required]: Session;
  [AuthenticationEnforcement.Optional]: Session | undefined;
  [AuthenticationEnforcement.None]: undefined;
};
type Zodifiable<P, Q, B, R> = {
  params?: ZodSchema<P>;
  query?: ZodSchema<Q>;
  body?: ZodSchema<B>;
  response?: ZodSchema<R>;
};
interface HandlerResult {
  statusCode: number;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  data: any;
}
export const defineHandler = <
  GParams,
  GQuery,
  GBody,
  GResponse,
  GAuthentication extends AuthenticationEnforcement,
>(
  opts: {
    schema: Zodifiable<GParams, GQuery, GBody, GResponse>;
    authentication: GAuthentication;
    rateLimit?: RateLimitTier;
    beforeHandlers?: Handler[];
    afterHandlers?: Handler[];
    openapi?: OpenApiRouteMeta;
  },
  handler: (
    req: Request<GParams, GResponse, GBody, GQuery>,
    res: Response<
      GResponse,
      {
        session: SessionPresent[GAuthentication];
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        unsafeStorage: any;
      }
    >,
    next: NextFunction,
  ) => Promise<HandlerResult | void>,
) => {
  if (opts.openapi) {
    registerOpenApiRoute({
      openapi: opts.openapi,
      authentication: opts.authentication,
      schema: opts.schema,
    });
  }

  return [
    ...(opts.rateLimit ? [rateLimitHandler(opts.rateLimit)] : []),
    async (req: Request, res: Response, next: NextFunction) => {
      try {
        try {
          opts.schema.params?.parse(req.params);
          opts.schema.query?.parse(req.query);
          opts.schema.body?.parse(req.body);
        } catch (e) {
          if (e instanceof ZodError) {
            throw new BadRequestError(e.message);
          }
          throw new InternalServerError("Unknown error parsing request");
        }

        let session: Session | undefined;
        if (opts.authentication !== AuthenticationEnforcement.None) {
          const authorization = req.headers.authorization;
          const queryToken = req.query.token as string | undefined;
          if (
            opts.authentication === AuthenticationEnforcement.Required &&
            !(authorization || queryToken)
          ) {
            throw new UnauthorizedError(
              "You must pass an authorization header",
            );
          }

          if (authorization || queryToken) {
            const token = authorization
              ? authorization.split(" ").at(1)
              : queryToken;
            session = token ? await validateSession(token) : undefined;
            if (session) extendSession(session);

            if (
              opts.authentication === AuthenticationEnforcement.Required &&
              !session
            ) {
              throw new UnauthorizedError("Token is not valid");
            }
          }
        }

        res.locals.session = session;

        next();
      } catch (e) {
        handleServerError(e, res);
      }
    },
    ...(opts.beforeHandlers || []),
    async (req: Request, res: Response, next: NextFunction) => {
      try {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const result = await handler(req as any, res as any, next);

        if (result) {
          let data = result.data;
          if (opts.schema.response) {
            try {
              data = opts.schema.response.parse(result.data);
            } catch (e) {
              if (e instanceof ZodError) {
                const routeLabel = opts.openapi
                  ? `${opts.openapi.method.toUpperCase()} ${opts.openapi.path}`
                  : req.path;
                throw new InternalServerError(
                  `Response validation failed for ${routeLabel}`,
                  { cause: e },
                );
              }
              throw e;
            }
          }
          res.status(result.statusCode).send(data);
        }
      } catch (e) {
        handleServerError(e, res);
      }
    },
    ...(opts.afterHandlers || []),
  ];
};

export class ServerError extends Error {
  constructor(
    public status: number,
    ...args: ConstructorParameters<typeof Error>
  ) {
    super(...args);
  }
}

export class BadRequestError extends ServerError {
  constructor(...args: ConstructorParameters<typeof Error>) {
    super(400, ...args);
  }
}

export class UnauthorizedError extends ServerError {
  constructor(...args: ConstructorParameters<typeof Error>) {
    super(401, ...args);
  }
}

export class ForbiddenError extends ServerError {
  constructor(...args: ConstructorParameters<typeof Error>) {
    super(403, ...args);
  }
}

export class NotFoundError extends ServerError {
  constructor(...args: ConstructorParameters<typeof Error>) {
    super(404, ...args);
  }
}

export class NotAcceptableError extends ServerError {
  constructor(...args: ConstructorParameters<typeof Error>) {
    super(406, ...args);
  }
}

export class PayloadTooLargeError extends ServerError {
  constructor(...args: ConstructorParameters<typeof Error>) {
    super(413, ...args);
  }
}

export class UnsupportedMediaTypeError extends ServerError {
  constructor(...args: ConstructorParameters<typeof Error>) {
    super(415, ...args);
  }
}

export class TooManyRequestsError extends ServerError {
  constructor(...args: ConstructorParameters<typeof Error>) {
    super(429, ...args);
  }
}

export class CreditLimitExceededHttpError extends ServerError {
  constructor(...args: ConstructorParameters<typeof Error>) {
    super(420, ...args);
  }
}

export class InternalServerError extends ServerError {
  constructor(...args: ConstructorParameters<typeof Error>) {
    super(500, ...args);
  }
}

