"use client";

import type { CSSProperties, ReactNode } from "react";
import { useEffect, useRef, useState } from "react";

/**
 * One observer serves every reveal on the page. Each element is watched until
 * it first appears, then dropped — nothing keeps observing after it has done
 * its job.
 */
const pending = new Map<Element, () => void>();

let sharedObserver: IntersectionObserver | null = null;

function observerFor(element: Element, onShown: () => void) {
  sharedObserver ??= new IntersectionObserver(
    (entries) => {
      for (const entry of entries) {
        if (!entry.isIntersecting) continue;

        pending.get(entry.target)?.();
        pending.delete(entry.target);
        sharedObserver?.unobserve(entry.target);
      }
    },
    { rootMargin: "0px 0px -10% 0px", threshold: 0.05 }
  );

  pending.set(element, onShown);
  sharedObserver.observe(element);

  return sharedObserver;
}

/** Tracks whether an element has entered the viewport at least once. */
export function useReveal<T extends HTMLElement>() {
  const ref = useRef<T>(null);
  const [shown, setShown] = useState(false);

  useEffect(() => {
    const element = ref.current;

    if (!element) return;

    const observer = observerFor(element, () => setShown(true));

    return () => {
      pending.delete(element);
      observer.unobserve(element);
    };
  }, []);

  return { ref, shown };
}

type RevealProps = {
  children: ReactNode;
  className?: string;
  /** Milliseconds to hold back after the element is seen, for staggering. */
  delay?: number;
  /** Screenshots settle further and slower than text does. */
  variant?: "text" | "media" | "bare";
  style?: CSSProperties;
};

/**
 * Fades and lifts its children into place the first time they are scrolled to.
 * The `bare` variant does none of that itself and only says when it was seen,
 * for children that have their own way of arriving.
 */
export function Reveal({ children, className, delay = 0, variant = "text", style }: RevealProps) {
  const { ref, shown } = useReveal<HTMLDivElement>();
  const settling = { text: "reveal", media: "reveal-media", bare: "" }[variant];

  return (
    <div
      ref={ref}
      className={`${settling} ${className ?? ""}`}
      data-shown={shown}
      style={delay ? ({ ...style, "--reveal-delay": `${delay}ms` } as CSSProperties) : style}
    >
      {children}
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

/**
 * Runs its callback on an animation frame after every scroll and resize, and
 * once on mount. A burst of events collapses into a single frame, and the
 * callback that runs is always the latest one, so callers can close over fresh
 * values without ever re-subscribing.
 *
 * Everything scroll-linked on the page is driven this way rather than by CSS
 * scroll timelines: the same code path then runs in every browser, and each
 * section can write exactly the numbers it needs onto its own markup.
 */
export function useScrollFrame(onFrame: () => void) {
  const latest = useRef(onFrame);

  useEffect(() => {
    latest.current = onFrame;
  });

  useEffect(() => {
    let frame = 0;

    const run = () => {
      frame = 0;
      latest.current();
    };

    const schedule = () => {
      frame ||= requestAnimationFrame(run);
    };

    run();
    window.addEventListener("scroll", schedule, { passive: true });
    window.addEventListener("resize", schedule);

    return () => {
      cancelAnimationFrame(frame);
      window.removeEventListener("scroll", schedule);
      window.removeEventListener("resize", schedule);
    };
  }, []);
}

/** Keeps a number inside 0 and 1. */
export function clamp(value: number) {
  return Math.min(1, Math.max(0, value));
}

"use client";

import { clamp } from "./scroll-frame";

/** A soft start and stop on each move, so it never reads as a jump cut. */
export function ease(t: number) {
  return t * t * (3 - 2 * t);
}

const asked = new Map<string, MediaQueryList>();

/**
 * A media query, kept around between frames. Read live rather than remembered,
 * so a resize or a change of preference takes hold on the next frame.
 */
export function asking(query: string) {
  let query_ = asked.get(query);

  if (!query_) {
    query_ = window.matchMedia(query);
    asked.set(query, query_);
  }

  return query_.matches;
}

/** Whether less motion was asked for. */
export function prefersCalm() {
  return asking("(prefers-reduced-motion: reduce)");
}

/** The share of a held screen one step rests for, given how long a move takes. */
export function holdOf(count: number, glide: number) {
  return (1 - (count - 1) * glide) / count;
}

/**
 * Where a sequence is, counted in steps, at a given point of the held screen. A
 * whole number is a step at rest; the fraction between two is a move underway.
 * Each step rests for the same stretch, and the moves between them are eased so
 * the sequence reads as one thing walking rather than a set of cuts.
 */
export function walkAt(progress: number, count: number, glide: number) {
  const hold = holdOf(count, glide);
  let rests = 0;

  for (let step = 0; step < count - 1; step += 1) {
    const leaves = rests + hold;

    if (progress <= leaves) return step;
    if (progress < leaves + glide) return step + ease((progress - leaves) / glide);

    rests = leaves + glide;
  }

  return count - 1;
}

/**
 * How far a held section has come, as 0 to 1. Read off the geometry on the
 * frame rather than from remembered offsets, so it survives a resize, a zoom,
 * and a browser restoring a scroll position in the middle of the section.
 */
export function heldAt(section: HTMLElement) {
  const { top, height } = section.getBoundingClientRect();
  const held = height - window.innerHeight;

  return held > 0 ? clamp(-top / held) : 0;
}

import { asset } from "@/lib/assets";

/**
 * Intrinsic size of the largest variant plus the widths that exist on disk.
 * Every shot is pre-rendered at these sizes under `public/screenshots/optimized`,
 * so nothing is resized at request time and no image optimizer is involved.
 */
const SHOTS = {
  "dashboard-web": { widths: [640, 1120], width: 1120, height: 839 },
  "recipe-web": { widths: [640, 1120], width: 1120, height: 839 },
  "cooking-web": { widths: [640, 1120], width: 1120, height: 839 },
  "calendar-web": { widths: [640, 1120], width: 1120, height: 839 },
  "groceries-web": { widths: [640, 1120], width: 1120, height: 839 },
  "dashboard-mobile": { widths: [192, 384], width: 384, height: 761 },
  "recipe-mobile": { widths: [192, 384], width: 384, height: 761 },
  "cooking-mobile": { widths: [192, 384], width: 384, height: 761 },
  "calendar-mobile": { widths: [192, 384], width: 384, height: 761 },
  "groceries-mobile": { widths: [192, 384], width: 384, height: 761 },
  // Not a capture but a photograph, and the only one on the page: the dish in
  // the hero's recipe fragment. Its master is 440 wide, so the second width is
  // an upscale the optimizer sharpens rather than detail that exists.
  "hero-dish": { widths: [440, 880], width: 880, height: 390 },
} as const;

type ShotProps = {
  base: keyof typeof SHOTS;
  alt: string;
  /** Rendered width hint for the browser's variant pick, e.g. "(min-width: 64rem) 34rem, 90vw". */
  sizes: string;
  className?: string;
};

function srcSet(base: string, theme: "light" | "dark", widths: readonly number[]) {
  return widths
    .map((width) => `${asset(`/screenshots/optimized/${base}-${theme}-${width}.webp`)} ${width}w`)
    .join(", ");
}

/**
 * A product screenshot in whichever theme is active.
 *
 * Both variants are in the markup and swapped with CSS, so the right one is on
 * screen before first paint with no hydration flash. Because the inactive
 * variant is `display: none`, a lazy loader never fetches it — only one image
 * is ever downloaded.
 */
export function Shot({ base, alt, sizes, className }: ShotProps) {
  const { widths, width, height } = SHOTS[base];
  const shared = { width, height, sizes, loading: "lazy", decoding: "async" } as const;

  return (
    <>
      <img
        {...shared}
        alt={alt}
        className={`block dark:hidden ${className ?? ""}`}
        src={asset(`/screenshots/optimized/${base}-light-${width}.webp`)}
        srcSet={srcSet(base, "light", widths)}
      />
      <img
        {...shared}
        alt={alt}
        className={`hidden dark:block ${className ?? ""}`}
        src={asset(`/screenshots/optimized/${base}-dark-${width}.webp`)}
        srcSet={srcSet(base, "dark", widths)}
      />
    </>
  );
}

