namespace treap {
    struct node_info {
        node_info *l, *r;
        int x, y, size;
        node_info() { }
        node_info(int _x) : l(0), r(0), x(_x), y(rng()), size(0) { }
    };
    using node = node_info *;
    node root = 0;
    bool setify = false;
    inline int size(node t) { return t ? t->size : 0; }
    inline void upd_size(node t) {
        if (t) t->size = size(t->l) + size(t->r) + 1;
    }
    void merge(node &t, node L, node R) {
        if (!L || !R) {
            t = L ? L : R;
        } else if (L->y > R->y) {
            merge(L->r, L->r, R);
            t = L;
        } else {
            merge(R->l, L, R->l);
            t = R;
        }
        upd_size(t);
    }
    void split(node t, int x, node &L, node &R) {
        if (!t) {
            L = R = 0;
        } else if (t->x <= x) {
            split(t->r, x, t->r, R);
            L = t;
        } else {
            split(t->l, x, L, t->l);
            R = t;
        }
        upd_size(t);
    }
    void insert(node &t, node to) {
        if (!t) {
            t = to;
        } else if (to->y > t->y) {
            split(t, to->x, to->l, to->r);
            t = to;
        } else {
            insert(to->x < t->x ? t->l : t->r, to);
        }
        upd_size(t);
    }
    bool remove(node &t, int x) {
        if (!t) return false;
        if (x == t->x) {
            node rem = t;
            merge(t, t->l, t->r);
            upd_size(t);
            delete rem;
            return true;
        }
        bool ok = remove(x < t->x ? t->l : t->r, x);
        upd_size(t);
        return ok;
    }
    bool find(node &t, int x) {
        return t ? (t->x == x || find(x < t->x ? t->l : t->r, x)) : false;
    }
    bool find(int x) { return find(root, x); }
    inline void insert(int x) {
        if (setify) {
            if (find(x)) return;
        }
        insert(root, new node_info(x));
    }
    inline void remove(int x) { remove(root, x); }
}

struct XorTrie {
    const int bits = 30;
    vector<vector<int>> go;
    int root = 0, cnt = 1;
    void build(int n) { go.assign((n + 1) * bits, vector<int>(2, -1)); }
    void insert(int x) {
        int v = root;
        for (int i = bits - 1; i >= 0; i--) {
            int b = x >> i & 1;
            if (go[v][b] == -1) go[v][b] = cnt++;
            v = go[v][b];
        }
    }
    int max_xor(int x) {
        int v = root;
        int ans = 0;
        if (cnt <= 1) return -1;
        for (int i = bits - 1; i >= 0; i--) {
            int b = x >> i & 1;
            int good = go[v][!b];
            int bad = go[v][b];
            if (good != -1) {
                v = good;
                ans |= 1 << i;
            } else v = bad;
        }
        return ans;
    }
    int min_xor(int x) {
        int flipped = x ^ ((1 << bits) - 1);
        int query = max_xor(flipped);
        if (query == -1) return -1;
        return x ^ flipped ^ query;
    }
} trie;

