            // Describe is ps-gated: it spawns only once ps confirms the selected host running.
            psFollowOptions.lineCallback(JSON.stringify([
                {
                    appHostPath: '/workspace/labs/ops/apphost.cs',
                    appHostPid: 125881,
                },
            ]));
