            assert.strictEqual(result.controller, 'editor');
            assert.strictEqual(launchService.launchCalls.length, 0);
            assert.strictEqual(launchService.resolveLaunchIsolationCalls, 0);
            assertResultOmitsIsolated(result);
        });

